def get_bundle_version() -> str:
    """Retrieve version string from integrity module or in-memory bundle asset."""
    try:
        from dwimsy.meta.integrity import version

        return version()
    except Exception:
        try:
            ver_text = get_asset_text("dwimsy/_version.py")
            m = re.search(r'__version__\s*=\s*["\']([^"\']+)["\']', ver_text)
            if m:
                return m.group(1)
        except Exception:
            pass
        return "0.1.6.0-dev"


def extract_b64_lzma_tar(
    b64_string: str,
    output_dir: str | Path,
    self_path: Optional[str | Path] = None,
    with_deps: bool = False,
) -> None:
    """Decode base64 -> decompress lzma -> extract tar to output_dir, and copy self to dwimsy/meta/unbundle.py."""
    out_path = Path(output_dir).resolve()
    out_path.mkdir(parents=True, exist_ok=True)

    tar_bytes = lzma.decompress(base64.b64decode(b64_string))

    with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:*") as tar:
        members_to_extract = []
        for m in tar.getmembers():
            norm_name = (m.name[2:] if m.name.startswith("./") else m.name)
            if not with_deps and (norm_name == "deps" or norm_name.startswith("deps/")):
                continue
            members_to_extract.append(m)

        try:
            tar.extractall(
                path=str(out_path), members=members_to_extract, filter="data"
            )
        except TypeError:
            tar.extractall(path=str(out_path), members=members_to_extract)

    # Set execute permissions for any .py files starting with a shebang
    for m in members_to_extract:
        if m.isfile():
            dest_file = out_path / (m.name[2:] if m.name.startswith("./") else m.name)
            if dest_file.suffix == ".py" and dest_file.is_file():
                try:
                    with open(dest_file, "rb") as f:
                        lead = f.read(2)
                    if lead == b"#!":
                        dest_file.chmod(dest_file.stat().st_mode | 0o111 | 0o755)
                except (OSError, PermissionError):
                    pass

    # Reconstitute self from the canonical elided unbundle.py stored in the payload.
    target_unbundle = out_path / "dwimsy" / "meta" / "unbundle.py"
    target_unbundle.parent.mkdir(parents=True, exist_ok=True)
    try:
        with _open_bundle_tar(b64_string) as src_tar:
            template_member = None
            for member in src_tar.getmembers():
                norm = member.name.lstrip("./")
                if norm == "dwimsy/meta/unbundle.py" and member.isfile():
                    template_member = member
                    break
            if template_member is None:
                raise FileNotFoundError("bundle does not contain canonical unbundle.py template")
            f = src_tar.extractfile(template_member)
            if f is None:
                raise FileNotFoundError("cannot read canonical unbundle.py template")
            template = f.read()
            template_mtime = float(template_member.mtime)

        target_unbundle.write_bytes(inject_blztar_bytes(template, b64_string))
        try:
            target_unbundle.chmod(0o755)
        except OSError:
            pass
        try:
            os.utime(target_unbundle, (template_mtime, template_mtime))
        except (OSError, PermissionError):
            pass
    except Exception:
        # Older bundles did not carry the canonical template. Fall back to the
        # executing script so those bundles remain readable, but do not use this
        # path for newly generated bundles.
        src_code = None
        candidates = []
        if self_path is not None:
            candidates.append(Path(self_path))
        try:
            candidates.append(Path(__file__))
        except (NameError, TypeError):
            pass
        if sys.argv and sys.argv[0]:
            candidates.append(Path(sys.argv[0]))
        for cand in candidates:
            try:
                p = cand.resolve()
                if p.is_file():
                    data = p.read_bytes()
                    if b"extract_b64_lzma_tar" in data and b"blztar" in data:
                        src_code = data
                        break
            except (OSError, ValueError):
                pass
        if src_code is not None:
            target_unbundle.write_bytes(src_code.replace(b"\r\n", b"\n").replace(b"\r", b"\n"))

    # Set each created directory's modification time to the max modification time of files within it
    all_dirs = [d for d in out_path.rglob("*") if d.is_dir()]
    all_dirs.append(out_path)
    for d in sorted(all_dirs, key=lambda p: len(p.parts), reverse=True):
        files_inside = [f for f in d.rglob("*") if f.is_file()]
        if files_inside:
            max_mtime = max(f.stat().st_mtime for f in files_inside)
            try:
                os.utime(d, (max_mtime, max_mtime))
            except (OSError, PermissionError):
                pass


def extract_deps(output_dir: str | Path, b64_string: Optional[str] = None) -> List[str]:
    """Extract frozen third-party reference dependencies into output_dir/deps."""
    out_path = Path(output_dir).resolve()
    deps_dir = out_path / "deps"
    deps_dir.mkdir(parents=True, exist_ok=True)

    extracted_names: List[str] = []

    with _open_bundle_tar(b64_string) as tar:
        dep_members = []
        for m in tar.getmembers():
            norm_name = (m.name[2:] if m.name.startswith("./") else m.name)
            if norm_name == "deps" or norm_name.startswith("deps/"):
                dep_members.append(m)
                if m.isfile():
                    extracted_names.append(norm_name)

        try:
            tar.extractall(path=str(out_path), members=dep_members, filter="data")
        except TypeError:
            tar.extractall(path=str(out_path), members=dep_members)

    for m in dep_members:
        if m.isfile():
            dest_file = out_path / (m.name[2:] if m.name.startswith("./") else m.name)
            if dest_file.suffix == ".py" and dest_file.is_file():
                try:
                    with open(dest_file, "rb") as f:
                        lead = f.read(2)
                    if lead == b"#!":
                        dest_file.chmod(dest_file.stat().st_mode | 0o111 | 0o755)
                except (OSError, PermissionError):
                    pass

    # Restore directory mtimes
    all_dirs = [d for d in deps_dir.rglob("*") if d.is_dir()]
    all_dirs.append(deps_dir)
    for d in sorted(all_dirs, key=lambda p: len(p.parts), reverse=True):
        files_inside = [f for f in d.rglob("*") if f.is_file()]
        if files_inside:
            max_mtime = max(f.stat().st_mtime for f in files_inside)
            try:
                os.utime(d, (max_mtime, max_mtime))
            except (OSError, PermissionError):
                pass

    return extracted_names


def _open_bundle_tar(b64_string: Optional[str] = None) -> tarfile.TarFile:
    payload = b64_string if b64_string is not None else blztar
    tar_bytes = lzma.decompress(base64.b64decode(payload))
    return tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:*")


def list_assets(b64_string: Optional[str] = None) -> List[str]:
    """List all file paths present in the bundle archive."""
    with _open_bundle_tar(b64_string) as tar:
        names = []
        for m in tar.getmembers():
            if m.isfile():
                name = (m.name[2:] if m.name.startswith("./") else m.name)
                names.append(name)
        return names


def get_asset(filename: str, b64_string: Optional[str] = None) -> bytes:
    """Extract a single file from the in-memory bundle payload as raw bytes."""
    norm_target = Path(filename).as_posix()
    with _open_bundle_tar(b64_string) as tar:
        for m in tar.getmembers():
            if m.isfile() and (m.name[2:] if m.name.startswith("./") else m.name) == norm_target:
                f = tar.extractfile(m)
                if f is not None:
                    return f.read()
    raise FileNotFoundError(f"Asset '{filename}' not found in bundle payload")


def get_asset_text(
    filename: str,
    b64_string: Optional[str] = None,
    encoding: str = "utf-8",
) -> str:
    """Extract a single file from the in-memory bundle payload as decoded text."""
    return get_asset(filename, b64_string=b64_string).decode(encoding)


def main(argv: Optional[List[str]] = None) -> None:
    """CLI entrypoint for standalone unbundle script."""
    import argparse

    parser = argparse.ArgumentParser(
        prog="dwimsy-unbundle",
        description="Extract dwimsy standalone bundle",
    )
    parser.add_argument(
        "-V",
        "--version",
        action="version",
        version=f"%(prog)s {get_bundle_version()}",
    )
    parser.add_argument("target_directory", help="Target directory for extraction")
    parser.add_argument(
        "--deps",
        "-d",
        action="store_true",
        help="Also extract frozen third-party reference dependencies into deps/",
    )
    args = parser.parse_args(argv)
    self_script = sys.argv[0] if argv is None else None
    extract_b64_lzma_tar(
        blztar, args.target_directory, self_path=self_script, with_deps=args.deps
    )
    print(f"Successfully extracted to {args.target_directory}")


class BundleFinder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    """Imports pure Python modules and assets directly from the in-memory blztar payload."""

    def __init__(self, b64_string: str, self_mod: Optional[types.ModuleType] = None):
        self.b64_string = b64_string
        self.self_mod = self_mod
        self._index: dict[str, bytes] = {}
        with _open_bundle_tar(b64_string) as tar:
            for member in tar.getmembers():
                if member.isfile():
                    norm = member.name.lstrip("./")
                    f = tar.extractfile(member)
                    if f is not None:
                        self._index[norm] = f.read()

    def find_spec(self, fullname: str, path=None, target=None):
        if not (
            fullname == "dwimsy"
            or fullname.startswith("dwimsy.")
            or fullname == "deps"
            or fullname.startswith("deps.")
        ):
            return None

        if fullname == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return importlib.machinery.ModuleSpec(
                name=fullname,
                loader=self,
                origin="<dwimsy-bundle>/dwimsy/meta/unbundle.py",
                is_package=False,
            )

        rel_base = fullname.replace(".", "/")
        pkg_path = f"{rel_base}/__init__.py"
        mod_path = f"{rel_base}.py"
        dep_pkg_path = f"deps/{rel_base}/__init__.py"
        dep_mod_path = f"deps/{rel_base}.py"

        for candidate, is_pkg in [
            (pkg_path, True),
            (mod_path, False),
            (dep_pkg_path, True),
            (dep_mod_path, False),
        ]:
            if candidate in self._index:
                spec = importlib.machinery.ModuleSpec(
                    name=fullname,
                    loader=self,
                    origin=f"<dwimsy-bundle>/{candidate}",
                    is_package=is_pkg,
                )
                if is_pkg:
                    spec.submodule_search_locations = [f"<dwimsy-bundle>/{rel_base}"]
                return spec
        return None

    def create_module(self, spec):
        if spec.name == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return self.self_mod
        return None

    def exec_module(self, module: types.ModuleType):
        if module.__spec__.name == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return
        origin = module.__spec__.origin
        if not origin or not origin.startswith("<dwimsy-bundle>/"):
            raise ImportError(f"Cannot execute module from origin {origin}")

        path = origin.removeprefix("<dwimsy-bundle>/")
        source = self._index.get(path)
        if source is None:
            raise ImportError(f"Missing bundled source for {path}")

        code = compile(source, origin, "exec")
        module.__file__ = origin
        exec(code, module.__dict__)


UNBUNDLE_PROG_PATTERN = re.compile(
    r"^(?:.*[/\\])?(?:(?:dwimsy[.\-_/ ])?(?:meta[.\-_/ ])?)?unbundle(?:\.py)?(?: |$)",
    re.IGNORECASE,
)


def is_unbundle_invocation(prog_name: Optional[str] = None) -> bool:
    """Return True if prog_name or sys.argv[0] indicates an unbundle command invocation."""
    if prog_name is None:
        prog_name = sys.argv[0] if sys.argv else ""
    return bool(UNBUNDLE_PROG_PATTERN.search(prog_name))


def bootstrap_in_memory_cli(argv: Optional[List[str]] = None) -> None:
    """Mount the bundle payload on sys.meta_path and dispatch to dwimsy.cli."""
    this_mod = sys.modules.get(__name__)
    sys.modules["dwimsy.meta.unbundle"] = this_mod
    bundle_finder = BundleFinder(blztar, self_mod=this_mod)
    sys.meta_path.insert(0, bundle_finder)

    if argv is not None:
        sys.argv = argv

    import dwimsy.cli.__main__ as cli_main

    test_mode = any(arg in ("--test", "-T") for arg in sys.argv[1:])
    old_bundle_build = os.environ.get("DWIMSY_BUNDLE_BUILD")
    if test_mode:
        os.environ["DWIMSY_BUNDLE_BUILD"] = "1"
    try:
        cli_main.main()
    finally:
        if test_mode:
            if old_bundle_build is None:
                os.environ.pop("DWIMSY_BUNDLE_BUILD", None)
            else:
                os.environ["DWIMSY_BUNDLE_BUILD"] = old_bundle_build


if __name__ == "__main__":
    if is_unbundle_invocation():
        main()
    else:
        bootstrap_in_memory_cli()
